#!/usr/bin/env python3
import json
import math
from pathlib import Path

import pandas as pd
import pyarrow as pa
import pyarrow.parquet as pq

SOURCE_A = Path('/data/source_a/users.json')
SOURCE_B = Path('/data/source_b/users.csv')
SOURCE_C = Path('/data/source_c/users.parquet')
OUT_PARQUET = Path('/app/merged_users.parquet')
OUT_CONFLICTS = Path('/app/conflicts.json')

SOURCE_ORDER = ['source_a', 'source_b', 'source_c']
ALIASES = {
    'user_id': ['user_id', 'id', 'userId'],
    'email': ['email', 'email_address'],
    'name': ['full_name', 'name', 'userName'],
    'created_date': ['registration_date', 'created_at', 'joined'],
}
OUTPUT_FIELDS = ['user_id', 'name', 'email', 'created_date', 'status']


def is_missing(value):
    if value is None:
        return True
    if isinstance(value, float) and math.isnan(value):
        return True
    if isinstance(value, str) and value.strip() == '':
        return True
    try:
        result = pd.isna(value)
        return bool(result) if not hasattr(result, '__len__') else False
    except Exception:
        return False


def to_python(value):
    if is_missing(value):
        return None
    if hasattr(value, 'item'):
        try:
            value = value.item()
        except Exception:
            pass
    if isinstance(value, pd.Timestamp):
        return value.strftime('%Y-%m-%d')
    if isinstance(value, (int, float, bool, str)):
        return value
    return str(value)


def to_user_id(value):
    value = to_python(value)
    if value is None or isinstance(value, bool):
        return None
    try:
        if isinstance(value, float):
            return int(value) if value.is_integer() else None
        text = str(value).strip()
        if text.endswith('.0'):
            text = text[:-2]
        return int(text)
    except (TypeError, ValueError):
        return None


def to_date(value):
    value = to_python(value)
    if value is None:
        return None
    try:
        timestamp = pd.to_datetime(value, errors='raise')
        if isinstance(timestamp, pd.Timestamp):
            return timestamp.strftime('%Y-%m-%d')
    except Exception:
        pass
    text = str(value).strip()
    return text if len(text) == 10 and text[4] == '-' and text[7] == '-' else None


def pick(row, aliases):
    for alias in aliases:
        if alias in row and not is_missing(row[alias]):
            return to_python(row[alias])
    return None


def read_sources():
    with SOURCE_A.open() as f:
        a_records = json.load(f)
    if isinstance(a_records, dict):
        a_records = a_records.get('users', a_records.get('data', [a_records]))
    b_records = pd.read_csv(SOURCE_B, dtype=str, keep_default_na=False).to_dict('records')
    c_records = pd.read_parquet(SOURCE_C).to_dict('records')
    return {
        'source_a': a_records,
        'source_b': b_records,
        'source_c': c_records,
    }


def normalize_sources(raw_sources):
    normalized = {}
    for source_name, records in raw_sources.items():
        by_user = {}
        for row in records:
            record = {field: pick(row, aliases) for field, aliases in ALIASES.items()}
            record['status'] = pick(row, ['status'])
            record['user_id'] = to_user_id(record['user_id'])
            record['created_date'] = to_date(record['created_date'])
            user_id = record['user_id']
            if user_id is None or user_id in by_user:
                continue
            by_user[user_id] = record
        normalized[source_name] = by_user
    return normalized


def values_equal(left, right):
    return left == right or (is_missing(left) and is_missing(right))


def merge(normalized):
    all_ids = sorted(set().union(*(set(users) for users in normalized.values())))
    rows = []
    conflicts = []

    for user_id in all_ids:
        row = {'user_id': user_id}
        for field in OUTPUT_FIELDS[1:]:
            selected = None
            present = {}
            for source_name in SOURCE_ORDER:
                source_row = normalized[source_name].get(user_id, {})
                value = source_row.get(field)
                if not is_missing(value):
                    present[source_name] = value
                    if selected is None:
                        selected = value
            row[field] = selected

            distinct = []
            for value in present.values():
                if not any(values_equal(value, seen) for seen in distinct):
                    distinct.append(value)
            if len(distinct) > 1:
                conflicts.append({
                    'user_id': user_id,
                    'field': field,
                    'values': present,
                    'selected': selected,
                })
        rows.append(row)
    return rows, conflicts


def write_outputs(rows, conflicts):
    table = pa.Table.from_pylist(rows, schema=pa.schema([
        ('user_id', pa.int64()),
        ('name', pa.string()),
        ('email', pa.string()),
        ('created_date', pa.string()),
        ('status', pa.string()),
    ]))
    pq.write_table(table, OUT_PARQUET)
    report = {'total_conflicts': len(conflicts), 'conflicts': conflicts}
    with OUT_CONFLICTS.open('w') as f:
        json.dump(report, f, indent=2)
        f.write('\n')


def main():
    normalized = normalize_sources(read_sources())
    rows, conflicts = merge(normalized)
    write_outputs(rows, conflicts)
    print(f'Wrote {len(rows)} users and {len(conflicts)} conflicts')


if __name__ == '__main__':
    main()
